//! Copies niri's action table, generated by Nix, into `OUT_DIR`.
//!
//! The table comes from `niri msg action --help` of the **pinned** binary, via
//! `nix/scripts/gen-niri-actions.py`. This build script does not generate it: it only
//! locates it. Generating it here would require running the compositor during
//! `cargo build`, and `cargo build` does not know which niri is the pinned one — Nix does.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_NIRI_ACTIONS");

    let generated = env::var("RONOCTUA_NIRI_ACTIONS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_NIRI_ACTIONS is not set.\n\
             \n\
             The action table is extracted from the PINNED niri by Nix. Enter\n\
             the environment with `nix develop` (or `direnv allow`), which sets the\n\
             variable, or build through the flake with `nix build`.\n\
             \n\
             Extracting it here would need the compositor to run in `cargo build`, and\n\
             cargo does not know which niri is the pinned one."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    // TWO files, from the same directory: the action table and the default
    // binds one. They are artefacts of the SAME niri commit, and that is why they come together —
    // separated, they could point at different versions of the compositor.
    let dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    let origin = PathBuf::from(&generated);
    let origin = origin.parent().unwrap_or(&origin).to_path_buf();
    for file in ["niri-actions.rs", "binds-default.rs"] {
        let destination = dir.join(file);
        // DELETE FIRST: the file comes from the store and `fs::copy` inherits the
        // read-only mode along with the content — see `ronoctua-tokens`'s build.rs
        // and the trap recorded in AGENTS.md.
        let _ = fs::remove_file(&destination);
        let kdl_of = origin.join(file);
        fs::copy(&kdl_of, &destination)
            .unwrap_or_else(|e| panic!("could not copy {kdl_of:?} -> {destination:?}: {e}"));
    }
}
